-- ParcelPoint official database schema and current operational seed data.
CREATE DATABASE IF NOT EXISTS parcelpoint CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE parcelpoint;

CREATE TABLE IF NOT EXISTS facility_packages (
  package_id VARCHAR(40) PRIMARY KEY, tracking VARCHAR(80) NOT NULL UNIQUE,
  recipient_id VARCHAR(40) NOT NULL, courier VARCHAR(80) NOT NULL,
  description VARCHAR(500) NOT NULL, package_size VARCHAR(30) NOT NULL,
  received_at DATETIME NOT NULL, status VARCHAR(20) NOT NULL, slot_id VARCHAR(160) NULL,
  assigned_at DATETIME NULL, assigned_by VARCHAR(150) NULL, events JSON NOT NULL,
  transit JSON NOT NULL, notice_id VARCHAR(40) NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS facility_claims (
  claim_id VARCHAR(40) PRIMARY KEY, receipt VARCHAR(80) NOT NULL UNIQUE,
  package_id VARCHAR(40) NOT NULL, recipient_id VARCHAR(40) NOT NULL,
  claimed_at DATETIME NOT NULL, verifier VARCHAR(150) NOT NULL, method VARCHAR(200) NOT NULL,
  reference_code VARCHAR(100) NOT NULL, proof VARCHAR(100) NOT NULL,
  CONSTRAINT fk_facility_claim_package FOREIGN KEY (package_id) REFERENCES facility_packages(package_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS facility_notices (
  notice_id VARCHAR(40) PRIMARY KEY, kind VARCHAR(30) NOT NULL, title VARCHAR(200) NOT NULL,
  body VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL, recipient_id VARCHAR(40) NOT NULL,
  package_id VARCHAR(40) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE,
  CONSTRAINT fk_facility_notice_package FOREIGN KEY (package_id) REFERENCES facility_packages(package_id)
) ENGINE=InnoDB;

DELETE FROM facility_notices;
DELETE FROM facility_claims;
DELETE FROM facility_packages;

